static uint64_t pool(Fixture *f,unsigned operation,uint64_t a,uint64_t b,SatchelGuestPoolStatus want){SatchelGuestPoolRequest request={operation,operation<=SATCHEL_GUEST_POOL_BUILDER_FLAGS?BUILDER:POOL,a,b};SatchelGuestPoolResult result={0};CHECK(satchel_guest_pools_execute(f->pools,f->cpu,&request,&result)==want);return result.value;}
